/**
 * worktree-ship-report.mjs — human-facing review / completion report templates.
 *
 * The templates are intentionally generated by code so Stop hooks and
 * ship-worktree responses point agents at the same approval/report contract.
 */

import { renderTemplateFromSections } from './section-template-renderer.mjs';

export function buildFileTree(files) {
  if (!Array.isArray(files) || files.length === 0) return '(no files)';
  const sorted = [...new Set(files.filter(Boolean))].sort();
  const root = {};
  for (const path of sorted) {
    const parts = path.split('/').filter(Boolean);
    let node = root;
    for (let i = 0; i < parts.length; i += 1) {
      const part = parts[i];
      const isLeaf = i === parts.length - 1;
      if (!Object.prototype.hasOwnProperty.call(node, part)) {
        node[part] = isLeaf ? null : {};
      } else if (node[part] === null && !isLeaf) {
        node[part] = {};
      }
      if (!isLeaf) node = node[part];
    }
  }
  const lines = [];
  const render = (node, prefix) => {
    Object.entries(node).forEach(([name, child], idx, entries) => {
      const isLast = idx === entries.length - 1;
      const connector = isLast ? '└── ' : '├── ';
      const suffix = child !== null ? '/' : '';
      lines.push(prefix + connector + name + suffix);
      if (child !== null) render(child, prefix + (isLast ? '    ' : '│   '));
    });
  };
  render(root, '');
  return lines.join('\n');
}

function valueOrDash(value) {
  if (value === null || value === undefined || value === '') return '-';
  return String(value);
}

function statusKind(status) {
  if (!status) return 'EDIT';
  if (status.startsWith('A')) return 'NEW';
  if (status.startsWith('D')) return 'DELETE';
  if (status.startsWith('R')) return 'RENAME';
  return 'EDIT';
}

export function parseNameStatusRows(nameStatusText) {
  if (!nameStatusText || typeof nameStatusText !== 'string') return [];
  return nameStatusText
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const [status, ...paths] = line.split(/\s+/);
      const path = paths.length > 1 ? `${paths[0]} -> ${paths[paths.length - 1]}` : paths[0];
      return { path, kind: statusKind(status), raw_status: status };
    })
    .filter((row) => row.path);
}

